def start_order(services):
    deps = {n: list(d) for n, d in services.items()}
    waves, done = [], set()
    while len(done) < len(services):
        wave = sorted(n for n in services
                      if n not in done and all(d in done for d in deps[n]))
        if not wave:
            return waves, "circular:" + ",".join(sorted(n for n in services if n not in done))
        waves.append(wave)
        done.update(wave)
    return waves, None

services = {"db": [], "cache": [],
            "api": ["db", "cache"], "worker": ["db"], "gateway": ["api"]}
waves, err = start_order(services)
for i, w in enumerate(waves):
    print("wave%d=%s" % (i, ",".join(w)))
print("err=%s" % err)
print("waves=%d" % len(waves))

cyclic = {"a": ["b"], "b": ["c"], "c": ["a"]}
