print("cycle_detected=%s" % (start_order(cyclic)[1] is not None))

def probe_events(probes, failure_threshold, success_threshold):
    state, fails, oks, events = "healthy", 0, 0, []
    for i, ok in enumerate(probes):
        if ok:
            fails, oks = 0, oks + 1
            if state == "unhealthy" and oks >= success_threshold:
                state = "healthy"
                events.append((i, "healthy"))
        else:
            oks, fails = 0, fails + 1
            if state == "healthy" and fails >= failure_threshold:
                state = "unhealthy"
                events.append((i, "unhealthy"))
    return state, events

