print("recover=%s" % probe_events([False, False, False, True, True], 3, 2)[1])

// Kahn：反复取入度为 0 的顶点，删除其出边；取不满则存在环
function topoSort(graph) {
  const nodes = Object.keys(graph);
  const indeg = new Map(nodes.map(n => [n, 0]));
  const succ = new Map(nodes.map(n => [n, []]));
  for (const n of nodes) {
    for (const d of graph[n]) {
      if (!indeg.has(d)) continue;
      indeg.set(n, indeg.get(n) + 1);
      succ.get(d).push(n);
    }
  }
  const ready = nodes.filter(n => indeg.get(n) === 0).sort();
  const order = [];
  while (ready.length) {
    const n = ready.shift();
    order.push(n);
    for (const m of succ.get(n)) {
      indeg.set(m, indeg.get(m) - 1);
      if (indeg.get(m) === 0) { ready.push(m); ready.sort(); }
    }
  }
  return { order, acyclic: order.length === nodes.length };
}

